# This code has the purpose of data analysis of the scan in m_hat.
# The files generated by the simulations is formatted as:
# O_* | O_*_error | N_T | N_S | M_HAT  (for finite temperature)
# O_* | O_*_error | N_T | N_S | M_HAT  (for zero temperature)
# O_* | O_*_error | N_T | N_S | M_HAT + delta_M_HAT  (for finite temperature)
# O_* | O_*_error | N_T | N_S | M_HAT + delta_M_HAT  (for zero temperature)
# ...
# for a given lattice size we renormalize every M_HAT and evaluate the observables, every 2 lines we have a point of the given lattice size.



#======================================
#        Libraries
#======================================


import numpy as np
import matplotlib.pyplot as plt



#======================================
#        Parameters
#======================================


D = 2

N_T = [4, 6, 8]

ratio = 5



#======================================
#		Reading and separating data
#         with functions
#======================================


def read_pairs(filename):
  rows = []
  with open(filename, "r") as f:
    for line in f:
      parts = line.strip().split(",")
      rows.append([float(parts[0]), float(parts[1]), int(parts[2]), int(parts[3]), float(parts[4])])
  return [(rows[i], rows[i+1]) for i in range(0, len(rows), 2)]
  

pairs_O1 = read_pairs("data1/data_O1.txt")
pairs_O2 = read_pairs("data1/data_O2.txt")
pairs_O3 = read_pairs("data1/data_O3.txt")



#======================================
#      Renormalize observables
#======================================


results = []

for (r1f, r1z), (r2f, r2z), (r3f, r3z) in zip(pairs_O1, pairs_O2, pairs_O3):

# Extract finite temperature values: m = mean, e = error
  m1f, e1f, N_T_f, N_S_f, M_HAT_f = r1f
  m2f, e2f = r2f[0], r2f[1]
  m3f, e3f = r3f[0], r3f[1]
    
# Extract zero temperature values (vacuum reference)
  m1z, e1z = r1z[0], r1z[1]
  m2z, e2z = r2z[0], r2z[1]
  m3z, e3z = r3z[0], r3z[1]
    
  # 1. Calculate the x-axis variable: T/m = 1 / (N_T * M_HAT)
  T_over_m = 1.0 / (N_T_f * M_HAT_f)

  # 2. Renormalized O1+O2-O3 combination (for energy density)
  combination_renorm = (m1f + m2f - m3f) - (m1z + m2z - m3z)
  combination_renorm_error = np.sqrt(e1f**2 + e2f**2 + e3f**2 + e1z**2 + e2z**2 + e3z**2)

  # 3. Renormalized O1 alone (for trace anomaly)
  O1_renorm = m1f - m1z
  O1_renorm_error = np.sqrt(e1f**2 + e1z**2)

  # 4. Scale by T^D (which is N_T^D) to get dimensionless physical quantities
  energy_density = (N_T_f**D / 2.0) * combination_renorm
  energy_density_error = (N_T_f**D / 2.0) * combination_renorm_error

  trace_anomaly = (N_T_f**D) * O1_renorm
  trace_anomaly_error = (N_T_f**D) * O1_renorm_error  

  # Store the results
  results.append((T_over_m, energy_density, energy_density_error, trace_anomaly, trace_anomaly_error, N_T_f))

# Sort results by N_T first, then by T/m to ensure smooth line plotting
results.sort(key=lambda row: (row[5], row[0]))


#======================================
#       Plotting the results
#======================================

fig, (ax1, ax2) = plt.subplots(1, 2, figsize=(14, 6))

# Group results by N_T instead of ratio
by_NT = {4: [], 6: [], 8: []}

for r in results:
  nt_val = r[5]
  if nt_val in by_NT:
     by_NT[nt_val].append(r)

# Visual styling
markers = {4: 'o', 6: 's', 8: 'D'}
colors = {4: 'blue', 6: 'red', 8: 'green'}

# --- Left Plot: Energy Density vs T/m ---
for nt_val, data in by_NT.items():
  if not data: continue
  x = [r[0] for r in data]  # T_over_m
  y = [r[1] for r in data]  # energy_density
  err = [r[2] for r in data] # error
    
  # Plot lines connecting points
  ax1.errorbar(x, y, yerr=err, fmt=markers[nt_val], mfc='none', mec=colors[nt_val], color=colors[nt_val], linestyle='dotted', alpha=1, linewidth=1, capsize=3, markersize=6, label=f'$N_T={nt_val}$')

# High-T continuum limit for free scalar field is pi/6
ax1.axhline(y=(np.pi/6), color='black', linestyle='dashed', label='$\\pi/6$ (High-T Limit)', alpha=0.75, linewidth=1)

ax1.set_xlabel('$T/m$', fontsize=12)
ax1.set_ylabel('$\\epsilon/T^2$', fontsize=12)
ax1.set_title('Energy Density ($N_s / N_t = 5$)', fontsize=13)
ax1.legend(loc='best')



# --- Right Plot: Trace Anomaly vs T/m ---

 #zoomed-in inset
axins = ax2.inset_axes([0.4, 0.1, 0.55, 0.4])
x1, x2 = 0.622, 1.4
y1, y2 = 0.184, 0.195

axins.set_xlim(x1,x2)
axins.set_ylim(y1,y2)

for nt_val, data in by_NT.items():
  if not data: continue
  x = [r[0] for r in data]  # T_over_m
  y = [r[3] for r in data]  # trace_anomaly
  err = [r[4] for r in data] # error
    
  ax2.errorbar(x, y, yerr=err, fmt=markers[nt_val], mfc='none', mec=colors[nt_val], color=colors[nt_val], linestyle='dotted', alpha=1, linewidth=1, capsize=3, markersize=6, label=f'$N_T={nt_val}$')

  axins.errorbar(x, y, yerr= err, fmt=markers[nt_val], mfc='none', mec=colors[nt_val], color=colors[nt_val], linestyle='dotted', alpha=1, linewidth=1, capsize=3, markersize=6 )

  

  

ax2.set_xlabel('$T/m$', fontsize=12)
ax2.set_ylabel('$(\\epsilon-P)/T^2$', fontsize=12)
ax2.set_title('Trace Anomaly ($N_s / N_t = 5$)', fontsize=13)
ax2.legend(loc='best')

plt.tight_layout()
plt.show()
